        mon = await makemon($c.relem(mons, mnum), u.ux, u.uy, MM.EMIN | MM.NOMSG);
        if (mon) {
            mon.isminion = 1;
            mon.mextra.emin.min_align = alignment;
            mon.mextra.emin.renegade = FALSE;
        }
